                self.pos += 1
                right = self.parse_unary()
                if op == '*':
                    result = result * right
                else:
                    result = int(result / right)
            return result

        def parse_unary(self):
            if self.pos < len(self.tokens) and self.tokens[self.pos] == ('OP', '-'):
                self.pos += 1
                return -self.parse_unary()
            elif self.pos < len(self.tokens) and self.tokens[self.pos] == ('OP', '+'):
                self.pos += 1
                return self.parse_unary()
            else:
                return self.parse_primary()

        def parse_primary(self):
            if self.pos < len(self.tokens) and self.tokens[self.pos][0] == 'NUM':
                result = self.tokens[self.pos][1]
                self.pos += 1
                return result
            elif self.pos < len(self.tokens) and self.tokens[self.pos] == ('OP', '('):
                self.pos += 1
                result = self.parse_expr()
                self.pos += 1
                return result
            return 0

        def is_unary_minus(self):
            if self.pos >= len(self.tokens):
                return True
            tok = self.tokens[self.pos]
            if tok == ('OP', '-'):
                return True
            if tok == ('OP', '+'):
                return True
            if tok == ('OP', '('):
                return True
            return False

